// --- Auth Context API ---
const AuthContext = createContext();

const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const checkUser = async () => {
            const token = localStorage.getItem('token');
            if (token) {
                if (CONFIG.USE_MOCK) {
                    setUser({ name: 'Guest Traveler', email: 'admin@nuurpath.com', role: 'admin' }); // Mock admin
                    setLoading(false);
                    return;
                }
                axios.defaults.headers.common['x-auth-token'] = token;
                try {
                    const res = await axios.get('/api/auth/me');
                    setUser(res.data);
                } catch (err) {
                    localStorage.removeItem('token');
                    delete axios.defaults.headers.common['x-auth-token'];
                }
            }
            setLoading(false);
        };
        checkUser();
    }, []);

    const login = async (email, password) => {
        setError(null);
        try {
            if (CONFIG.USE_MOCK) {
                const role = email === 'admin@nuurpath.com' ? 'admin' : 'user';
                const name = role === 'admin' ? 'Admin' : 'Mock User';
                setUser({ name, email, role });
                localStorage.setItem('token', 'mock_token');
                return;
            }
            const res = await axios.post('/api/auth/login', { email, password });
            localStorage.setItem('token', res.data.token);
            axios.defaults.headers.common['x-auth-token'] = res.data.token;
            const userRes = await axios.get('/api/auth/me');
            setUser(userRes.data);
        } catch (err) {
            const errorMessage = err.response?.data?.msg || "Login failed. Please check your credentials.";
            setError(errorMessage);
            console.error(err);
        }
    };

    const register = async (name, email, password) => {
        setError(null);
        try {
            if (CONFIG.USE_MOCK) {
                setUser({ name, email, role: 'user' });
                localStorage.setItem('token', 'mock_token');
                return;
            }
            const res = await axios.post('/api/auth/register', { name, email, password });
            localStorage.setItem('token', res.data.token);
            axios.defaults.headers.common['x-auth-token'] = res.data.token;
            setUser(res.data.user || res.data);
        } catch (err) {
            const errorMessage = err.response?.data?.msg || "Registration failed. Please try again.";
            setError(errorMessage);
            console.error(err);
        }
    };

    const logout = () => {
        localStorage.removeItem('token');
        delete axios.defaults.headers.common['x-auth-token'];
        setUser(null);
    };

    const clearError = () => {
        setError(null);
    };

    const isAuthenticated = !!user;

    return (
        <AuthContext.Provider value={{ user, loading, error, login, register, logout, isAuthenticated, clearError }}>
            {children}
        </AuthContext.Provider>
    );
};

const LanguageProvider = ({ children }) => {
    const [currentLanguage, setCurrentLanguage] = useState('en'); // Default language
    const t = useCallback((key) => translations[currentLanguage][key] || key, [currentLanguage]);

    return (
        <LanguageContext.Provider value={{ currentLanguage, setCurrentLanguage, t }}>{children}</LanguageContext.Provider>
    );
};

const useAuth = () => useContext(AuthContext);

// --- Route Protectors ---

const PrivateRoute = ({ children }) => {
    const { isAuthenticated, loading } = useAuth();
    if (loading) return <div className="p-20 text-center font-bold">Verifying Session...</div>;
    return isAuthenticated ? children : <Navigate to="/login" replace />;
};

const AdminRoute = ({ children }) => {
    const { isAuthenticated, user, loading } = useAuth();
    if (loading) return <div className="p-20 text-center font-bold">Verifying Permissions...</div>;
    if (isAuthenticated && user && user.role === 'admin') return children;
    return <Navigate to="/dashboard" replace />;
};

