const PackageForm = ({ packageToEdit, onSuccess, onCancel }) => {
    const [formState, setFormState] = useState({
        title: packageToEdit?.title || '',
        destination: packageToEdit?.destination || '',
        duration: packageToEdit?.duration || '',
        type: packageToEdit?.type || 'leisure',
        price: packageToEdit?.price || '',
        description: packageToEdit?.description || '',
        isFeatured: packageToEdit?.isFeatured || false,
        existingImages: packageToEdit?.images || [],
    });
    const [newImageFiles, setNewImageFiles] = useState([]);
    const [isUploading, setIsUploading] = useState(false);
    const [uploadProgress, setUploadProgress] = useState(0);

    const quillRef = React.useRef(null);

    const handleCtaClick = () => {
        if (quillRef.current) {
            const quill = quillRef.current.getEditor();
            const range = quill.getSelection(true);
            const ctaButtonHtml = `<p style="text-align: center;"><a href="/contact" style="display: inline-block; padding: 12px 24px; background-color: #ecd106eb; color: #0c1b33; text-decoration: none; font-weight: bold; border-radius: 8px;">Book This Package</a></p>`;
            quill.clipboard.dangerouslyPasteHTML(range.index, ctaButtonHtml, 'user');
        }
    };

    const handleVideoEmbed = () => {
        const url = prompt("Enter video URL (YouTube or Vimeo):");
        if (!url) return;

        const getYoutubeVideoId = (url) => {
            const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
            const match = url.match(regExp);
            return (match && match[2].length === 11) ? match[2] : null;
        };

        const youtubeId = getYoutubeVideoId(url);

        const embedUrl = youtubeId ? `https://www.youtube.com/embed/${youtubeId}` : url;

        const quill = quillRef.current.getEditor();
        const range = quill.getSelection(true);
        quill.insertEmbed(range.index, 'video', embedUrl, 'user');
        quill.setSelection(range.index + 1, 'silent');
    };

    const quillModules = {
        toolbar: [
            [{ 'header': [1, 2, 3, 4, false] }],
            ['bold', 'italic', 'underline', 'strike'],
            [{ 'list': 'ordered'}, { 'list': 'bullet' }],
            [{ 'indent': '-1'}, { 'indent': '+1' }],
            [{ 'color': [] }, { 'background': [] }],
            ['link', 'video', 'ctaButton'],
            ['clean']
        ],
        handlers: {
            'ctaButton': handleCtaClick,
            'video': handleVideoEmbed,
        },
    };

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormState(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));
    };

    const handleDescriptionChange = (content) => {
        setFormState(prev => ({ ...prev, description: content }));
    };

    const handleFileChange = (e) => {
        setNewImageFiles(Array.from(e.target.files));
    };

    const handleRemoveExistingImage = (imageUrl) => {
        setFormState(prev => ({
            ...prev,
            existingImages: prev.existingImages.filter(url => url !== imageUrl),
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsUploading(true);
        setUploadProgress(0);

        const formData = new FormData();

        Object.keys(formState).forEach(key => {
            if (key !== 'existingImages') {
                formData.append(key, formState[key]);
            }
        });

        formState.existingImages.forEach(url => {
            formData.append('existingImages', url);
        });

        newImageFiles.forEach(file => {
            formData.append('images', file);
        });

        try {
            const config = {
                onUploadProgress: (progressEvent) => {
                    const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);
                    setUploadProgress(percentCompleted);
                }
            };

            if (packageToEdit?.id) {
                await axios.put(`/api/packages/${packageToEdit.id}`, formData, config);
            } else {
                await axios.post('/api/packages', formData, config);
            }

            onSuccess();
        } catch (err) {
            console.error("Failed to save package", err);
            alert("Error saving package. Check console for details.");
        } finally {
            setIsUploading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[200] animate-fade-in">
            <div className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-2xl">
                <h2 className="text-2xl font-black uppercase tracking-tighter mb-6">
                    {packageToEdit?.id ? 'Edit Package' : 'Create New Package'}
                </h2>
                <form onSubmit={handleSubmit} className="space-y-4 max-h-[70vh] overflow-y-auto pr-4">
                    <input name="title" value={formState.title} onChange={handleChange} placeholder="Package Title" required className="w-full p-3 bg-gray-100 rounded-lg font-bold" />
                    <div className="grid grid-cols-2 gap-4">
                        <input name="destination" value={formState.destination} onChange={handleChange} placeholder="Destination" required className="w-full p-3 bg-gray-100 rounded-lg font-bold" />
                        <input name="duration" value={formState.duration} onChange={handleChange} placeholder="Duration (e.g., 10 Days)" required className="w-full p-3 bg-gray-100 rounded-lg font-bold" />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <select name="type" value={formState.type} onChange={handleChange} required className="w-full p-3 bg-gray-100 rounded-lg font-bold">
                            <option value="leisure">Leisure</option>
                            <option value="umrah">Umrah</option>
                            <option value="hajj">Hajj</option>
                        </select>
                        <input type="number" step="0.01" name="price" value={formState.price} onChange={handleChange} placeholder="Price" required className="w-full p-3 bg-gray-100 rounded-lg font-bold" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">New Images</label>
                        <input type="file" multiple accept="image/*" onChange={handleFileChange} className="w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"/>
                    </div>
                    {formState.existingImages.length > 0 && (
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">Current Images</label>
                            <div className="grid grid-cols-3 sm:grid-cols-4 gap-4">
                                {formState.existingImages.map(url => (
                                    <div key={url} className="relative">
                                        <img src={`${CONFIG.API_BASE_URL}${url}`} alt="Package Preview" className="w-full h-24 object-cover rounded-lg" />
                                        <button type="button" onClick={() => handleRemoveExistingImage(url)} className="absolute -top-2 -right-2 bg-red-600 text-white rounded-full w-6 h-6 flex items-center justify-center font-bold text-sm">&times;</button>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                    <ReactQuill
                        theme="snow"
                        ref={quillRef}
                        value={formState.description}
                        onChange={handleDescriptionChange}
                        modules={quillModules}
                    />
                    <div className="flex items-center gap-2 pt-2">
                        <input
                            id="isFeatured"
                            name="isFeatured"
                            type="checkbox"
                            checked={formState.isFeatured}
                            onChange={handleChange}
                            className="h-4 w-4 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                        />
                        <label htmlFor="isFeatured" className="font-bold text-sm text-gray-700">
                            Feature on Homepage
                        </label>
                    </div>
                    {isUploading && (
                        <div className="w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-700">
                            <div className="bg-blue-600 h-2.5 rounded-full transition-all duration-300" style={{ width: `${uploadProgress}%` }}></div>
                        </div>
                    )}
                    <div className="flex justify-end gap-4 pt-4">
                        <button type="button" onClick={onCancel} disabled={isUploading} className="px-6 py-2 rounded-lg border-2 border-gray-300 font-bold disabled:opacity-50">Cancel</button>
                        <button type="submit" disabled={isUploading} className="px-6 py-2 rounded-lg bg-[#0c1b33] text-white font-bold disabled:opacity-50 disabled:bg-gray-500">
                            {isUploading ? `Uploading... ${uploadProgress}%` : 'Save Package'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

const AdminDashboard = () => {
    const { user } = useAuth();
    const { t } = useContext(LanguageContext);
    const [bookings, setBookings] = useState([]);
    const [packages, setPackages] = useState([]);
    const [featuredPackages, setFeaturedPackages] = useState([]);
    const [editingPackage, setEditingPackage] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [pagination, setPagination] = useState({ currentPage: 1, totalPages: 1 });
    const [searchTerm, setSearchTerm] = useState('');
    const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('');

    // Debounce search input to avoid excessive API calls
    useEffect(() => {
        const timerId = setTimeout(() => {
            setSearchTerm(debouncedSearchTerm);
            setPagination(p => ({ ...p, currentPage: 1 })); // Reset to page 1 on new search
        }, 500);

        return () => {
            clearTimeout(timerId);
        };
    }, [debouncedSearchTerm]);

    const fetchData = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            if (CONFIG.USE_MOCK) {
                const limit = 5;
                const filtered = MOCK_PACKAGES.filter(p => 
                    p.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                    p.destination.toLowerCase().includes(searchTerm.toLowerCase())
                );
                const offset = (pagination.currentPage - 1) * limit;
                setBookings(MOCK_BOOKINGS);
                setPackages(filtered.slice(offset, offset + limit));
                setPagination({
                    currentPage: pagination.currentPage,
                    totalPages: Math.ceil(filtered.length / limit),
                });
            } else {
                const bookingsPromise = axios.get('/api/bookings/all');
                const packagesPromise = axios.get(`/api/packages?page=${pagination.currentPage}&limit=5&search=${searchTerm}`);
                const featuredPackagesPromise = axios.get('/api/packages?featured=true');
                const [bookingsRes, packagesRes, featuredPackagesRes] = await Promise.all([bookingsPromise, packagesPromise, featuredPackagesPromise]);
                setBookings(bookingsRes.data);
                setPackages(packagesRes.data.packages);
                setPagination({
                    currentPage: packagesRes.data.currentPage,
                    totalPages: packagesRes.data.totalPages,
                });
                setFeaturedPackages(featuredPackagesRes.data);
            }
        } catch (err) {
            setError("Failed to fetch admin data.");
            console.error("Failed to fetch admin data", err);
        } finally {
            setLoading(false);
        }
    }, [pagination.currentPage, searchTerm]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const handleSaveSuccess = () => {
        setEditingPackage(null);
        fetchData();
    };

    const handleDeletePackage = async (packageId) => {
        if (window.confirm("Are you sure you want to delete this package?")) {
            try {
                await axios.delete(`/api/packages/${packageId}`);
                if (packages.length === 1 && pagination.currentPage > 1) {
                    setPagination(p => ({ ...p, currentPage: p.currentPage - 1 }));
                } else {
                    fetchData();
                }
            } catch (err) {
                console.error("Failed to delete package", err);
                alert("Error deleting package.");
            }
        }
    };

    const handleOnDragEnd = async (result) => {
        if (!result.destination) return;

        const items = Array.from(featuredPackages);
        const [reorderedItem] = items.splice(result.source.index, 1);
        items.splice(result.destination.index, 0, reorderedItem);

        setFeaturedPackages(items); // Optimistic UI update

        const packageIds = items.map(p => p.id);

        try {
            await axios.put('/api/packages/reorder-featured', { packageIds });
        } catch (err) {
            console.error("Failed to reorder packages", err);
            alert("Failed to save new order. Reverting.");
            fetchData(); // Revert on error
        }
    };

    const handleStatusUpdate = async (bookingId, newStatus) => {
        const originalBookings = [...bookings];
        const updatedBookings = bookings.map(b =>
            b.id === bookingId ? { ...b, status: newStatus } : b
        );
        setBookings(updatedBookings);

        try {
            await axios.put(`/api/bookings/${bookingId}/status`, { status: newStatus });
        } catch (err) {
            console.error("Failed to update booking status", err);
            alert("Failed to update status. Reverting changes.");
            setBookings(originalBookings); // Revert on error
        }
    };

    return (
        <div className="bg-gray-50 min-h-screen py-20 animate-fade-in">
            {editingPackage && (
                <PackageForm 
                    packageToEdit={editingPackage.id ? editingPackage : {}} 
                    onSuccess={handleSaveSuccess}
                    onCancel={() => setEditingPackage(null)}
                />
            )}
            <div className="container mx-auto px-4">
                <div className="bg-white p-12 rounded-[3rem] shadow-xl mb-12 border border-gray-100">
                    <h2 className="text-4xl font-black uppercase tracking-tighter text-[#0c1b33] mb-4 leading-none">Admin Command Center</h2>
                    <p className="text-gray-400 font-bold uppercase tracking-widest text-[10px] mt-1">{t('marhaba')}, {user?.name} ({user?.email})</p>
                </div>

                {loading ? <div className="text-center p-10">Loading admin data...</div> : error ? <div className="text-center p-10 text-red-500">{error}</div> : (
                    <div className="space-y-8">
                        <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border border-gray-100">
                            <div className="flex justify-between items-center mb-6">
                                <h3 className="text-2xl font-black uppercase tracking-tighter text-[#0c1b33] w-1/3">Manage Packages</h3>
                                <input
                                    type="text"
                                    placeholder="Search by title or destination..."
                                    value={debouncedSearchTerm}
                                    onChange={(e) => setDebouncedSearchTerm(e.target.value)}
                                    className="p-2 border rounded-lg w-1/3"
                                />
                                <button onClick={() => setEditingPackage({})} className="px-4 py-2 bg-green-500 text-white rounded-lg font-bold text-sm">Add New Package</button>
                            </div>
                            <ul className="space-y-3">
                                {packages.map(p => (
                                    <li key={p.id} className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                                        <div>
                                            <p className="font-bold">{p.title}</p>
                                            <p className="text-sm text-gray-500">${p.price.toLocaleString()} • {p.type}</p>
                                        </div>
                                        <div className="flex gap-2">
                                            <button onClick={() => setEditingPackage(p)} className="px-3 py-1 bg-blue-100 text-blue-800 rounded font-bold text-xs">Edit</button>
                                            <button onClick={() => handleDeletePackage(p.id)} className="px-3 py-1 bg-red-100 text-red-800 rounded font-bold text-xs">Delete</button>
                                        </div>
                                    </li>
                                ))}
                            </ul>
                            <div className="flex justify-between items-center mt-6">
                                <button
                                    onClick={() => setPagination(p => ({ ...p, currentPage: p.currentPage - 1 }))}
                                    disabled={pagination.currentPage <= 1 || loading}
                                    className="px-4 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold disabled:opacity-50"
                                >
                                    Previous
                                </button>
                                <span className="font-bold text-sm">
                                    Page {pagination.currentPage} of {pagination.totalPages || 1}
                                </span>
                                <button
                                    onClick={() => setPagination(p => ({ ...p, currentPage: p.currentPage + 1 }))}
                                    disabled={pagination.currentPage >= pagination.totalPages || loading}
                                    className="px-4 py-2 bg-gray-200 text-gray-800 rounded-lg font-bold disabled:opacity-50"
                                >
                                    Next
                                </button>
                            </div>
                        </div>
                        <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border border-gray-100">
                            <h3 className="text-2xl font-black uppercase tracking-tighter text-[#0c1b33]">Reorder Featured Packages</h3>
                            <p className="text-sm text-gray-500 mb-4">Drag and drop to change the order on the homepage.</p>
                            <DragDropContext onDragEnd={handleOnDragEnd}>
                                <Droppable droppableId="featuredPackages">
                                    {(provided) => (
                                        <ul {...provided.droppableProps} ref={provided.innerRef} className="space-y-3">
                                            {featuredPackages.map((p, index) => (
                                                <Draggable key={p.id.toString()} draggableId={p.id.toString()} index={index}>
                                                    {(provided) => (
                                                        <li
                                                            ref={provided.innerRef}
                                                            {...provided.draggableProps}
                                                            {...provided.dragHandleProps}
                                                            className="flex items-center p-3 bg-gray-100 rounded-lg cursor-grab active:cursor-grabbing"
                                                        >
                                                            <span className="mr-4 text-gray-400 font-bold w-6 text-center">{index + 1}</span>
                                                            <p className="font-bold">{p.title}</p>
                                                        </li>
                                                    )}
                                                </Draggable>
                                            ))}
                                            {provided.placeholder}
                                        </ul>
                                    )}
                                </Droppable>
                            </DragDropContext>
                        </div>

                        <div className="bg-white p-10 rounded-[2.5rem] shadow-xl border border-gray-100">
                            <h3 className="text-2xl font-black uppercase tracking-tighter text-[#0c1b33] mb-6">Manage Bookings</h3>
                            <ul className="space-y-3">
                                {bookings.map(b => (
                                    <li key={b.id} className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
                                        <div>
                                            <p className="font-bold">{b.Package?.title || b.packageTitle || 'N/A'}</p>
                                            <p className="text-sm text-gray-500">User: {b.User?.name || b.userId || 'N/A'}</p>
                                        </div>
                                        <select value={b.status} onChange={(e) => handleStatusUpdate(b.id, e.target.value)} className={`text-xs font-bold border rounded-md p-1 ${ b.status === 'Confirmed' ? 'bg-green-100 text-green-800 border-green-200' : b.status === 'Cancelled' ? 'bg-red-100 text-red-800 border-red-200' : 'bg-yellow-100 text-yellow-800 border-yellow-200' }`}>
                                            <option value="Pending">Pending</option>
                                            <option value="Confirmed">Confirmed</option>
                                            <option value="Cancelled">Cancelled</option>
                                        </select>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

